	constexpr bool isObservingBuiltin(std::string_view a_name, bool a_method) {
		for (const auto& entry : BUILTIN_OBSERVING_METHODS) {
			if (a_method && entry == a_name) { return true; }
		}
		for (const auto& entry : BUILTIN_OBSERVING_FUNCTIONS) {
			if (!a_method && entry == a_name) { return true; }
		}
		return false;
	}
